import {DEFAULTS,calculateScenario,scenarioToCSV} from './model.js';
import {BUSINESS_DEFAULTS,calculateBusiness,businessToCSV} from './business.js';
import {loadState,saveState,buildHash,parseHash,defaults,STORAGE_KEY} from './state.js';

const REPO='https://github.com/VikramMenon09/carbon-commons';
const $=(selector)=>document.querySelector(selector);
const esc=(value)=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=0)=>new Intl.NumberFormat('en-US',{maximumFractionDigits:d}).format(n);
const money=(n)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const compact=(n)=>Math.abs(n)>=1e15?n.toExponential(1):new Intl.NumberFormat('en-US',{notation:Math.abs(n)>=10000?'compact':'standard',maximumFractionDigits:Math.abs(n)>=10000?1:0}).format(n);
const cash=(n)=>`${n<0?'−':''}$${compact(Math.abs(n))}`;
const signed=(n)=>`${n>0?'+':n<0?'−':''}${money(Math.abs(n))}`;
const years=(n)=>n===null?'Not defined':n>0&&n<.1?'less than 0.1':n>999?compact(n):num(n,1);
const pct=(n)=>n===null?'Not defined':`${Math.abs(n)>=1e6?compact(n):num(n===0?0:n,1)}%`;
const tonnes=(n)=>n>0&&n<.1?'&lt;0.1':n>=10000?compact(n):num(n,1);
const icons={leaf:'<path d="M5 19c-2-10 4-16 15-15 1 11-5 17-15 15ZM5 19 15 9m-4 4V8m0 5h5"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 9h18m-5 4h5m-4 3h.01"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',save:'<path d="M6 3h12v18l-6-4-6 4Z"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v4h16v-4"/>',link:'<path d="m10 14 4-4m-6 7-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 3a4 4 0 0 0 6 0l4-4a4 4 0 0 0-6-6l-2 2" transform="translate(1 1) scale(.9)"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m3 10v-3a6 6 0 0 0-2-4"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.info}</svg>`;
let storage;try{storage=window.localStorage;}catch{storage={getItem(){throw Error('Unavailable')},setItem(){throw Error('Unavailable')}};}
const loaded=loadState(storage);let state=loaded.state;let mode='business';let activePreset='manufacturer';let current=null;let toastTimer;let announcementTimer;let storageWarning=loaded.warning;
const presets={
 business:[
  {id:'manufacturer',label:'Small manufacturer',input:{...BUSINESS_DEFAULTS}},
  {id:'cafe',label:'Neighborhood café',input:{revenue:400000,operatingCost:340000,annualTonnes:40,carbonPrice:50,reductionPercent:25,investment:15000,annualSavings:4000}},
  {id:'studio',label:'Digital studio',input:{revenue:600000,operatingCost:480000,annualTonnes:15,carbonPrice:50,reductionPercent:40,investment:8000,annualSavings:1800}}
 ],
 policy:[
  {id:'balanced',label:'Shared transition',input:{...DEFAULTS}},
  {id:'dividend',label:'Full household dividend',input:{carbonPrice:75,rebateShare:100,response:10,householdSize:2.5}},
  {id:'public',label:'Public investment',input:{carbonPrice:100,rebateShare:25,response:10,householdSize:2.5}}
 ]
};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4300);}
function persist(){if(!saveState(storage,state)&&!storageWarning){storageWarning='Your browser is not saving this session. Use a scenario link or CSV to keep your work.';toast(storageWarning);}}
function field(key,label,{prefix='',suffix='',min=0,max=1e12,step='any',help=''}={}){return `<div class="field"><label for="${key}">${label}</label><div class="input-wrap">${prefix?`<span class="unit-prefix">${prefix}</span>`:''}<input id="${key}" name="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${state[mode][key]}" class="${prefix?'has-prefix':''} ${suffix?'has-suffix':''}" ${help?`aria-describedby="${key}-help"`:''}>${suffix?`<span class="unit-suffix">${suffix}</span>`:''}</div>${help?`<small id="${key}-help">${help}</small>`:''}</div>`;}
function range(key,label,min,max,step,format,help=''){const value=state[mode][key];const onStep=Math.abs((value-min)/step-Math.round((value-min)/step))<1e-8;return `<div class="field"><div class="range-heading"><label for="${key}">${label}</label><output id="${key}-value" for="${key}">${format(value)}</output></div><input type="range" id="${key}" name="${key}" min="${min}" max="${max}" step="${onStep?step:'any'}" data-step="${step}" value="${value}" aria-valuetext="${esc(format(value))}" ${help?`aria-describedby="${key}-help"`:''}><div class="range-endpoints"><span>${format(min)}</span><span>${format(max)}</span></div>${help?`<small id="${key}-help">${help}</small>`:''}</div>`;}
const formats={carbonPrice:v=>`$${num(v,2)}/t`,reductionPercent:v=>`${num(v,2)}%`,rebateShare:v=>`${num(v,2)}%`,response:v=>`${num(v,2)}%`,householdSize:v=>`${num(v,2)} people`};
function businessForm(){return `<p class="form-section-label">Your business · annual figures</p><div class="field-row">${field('revenue','Revenue',{prefix:'$'})}${field('operatingCost','Operating costs',{prefix:'$'})}</div>${field('annualTonnes','Baseline emissions',{suffix:'t CO₂e',max:1e9,help:'Total annual emissions assumed subject to the charge.'})}${range('carbonPrice','Carbon price',0,200,5,formats.carbonPrice)}<div class="form-divider"></div><p class="form-section-label">Your lower-carbon investment</p>${range('reductionPercent','Emissions reduction',0,100,1,formats.reductionPercent)}<div class="field-row">${field('investment','Upfront cost',{prefix:'$'})}${field('annualSavings','Yearly savings',{prefix:'$'})}</div><p style="font-size:12px;color:var(--muted);line-height:1.6">Operating costs and savings exclude carbon charges. Enter savings net of extra maintenance costs.</p>`;}
function policyForm(){return `<p class="form-section-label">Design a carbon price</p>${range('carbonPrice','Carbon price',0,200,5,formats.carbonPrice)}${range('rebateShare','Revenue returned',0,100,5,formats.rebateShare,'An equal annual dividend for every household.')}<div class="form-divider"></div><p class="form-section-label">Explore the assumptions</p>${range('response','Reduction at $100/t',0,40,1,formats.response,'An assumed response, not a measured forecast. It scales with the carbon price.')} ${range('householdSize','Average household size',1,6,.1,formats.householdSize,'Scales each group’s emissions. Incomes stay fixed.')}`;}
function renderLab(){
 const match=presets[mode].find(p=>Object.keys(defaults[mode]).every(k=>p.input[k]===state[mode][k]));activePreset=match?.id||'';
 $('#app').innerHTML=`${storageWarning?`<p class="storage-warning">${esc(storageWarning)}</p>`:''}<div class="lab-topline"><div class="preset-bar" role="group" aria-label="Illustrative scenarios">${presets[mode].map(p=>`<button type="button" data-preset="${p.id}" aria-pressed="${p.id===activePreset}">${p.label}</button>`).join('')}</div><span class="model-label">${icon('info')} Hypothetical inputs · annual USD</span></div><div class="lab-layout"><aside class="controls" aria-label="Scenario inputs"><div class="panel-heading"><h2>Your assumptions</h2><button class="reset" type="button" id="reset">Reset</button></div><form id="scenario-form" class="form-body" novalidate>${mode==='business'?businessForm():policyForm()}<p id="form-error" class="form-error" role="alert"></p></form><div class="control-footer">${mode==='business'?'A transparent “what if,” using your inputs. All business presets are hypothetical.':'Five equally weighted, synthetic household groups. These are accounting examples, not country estimates.'}</div></aside><section class="results" aria-label="Scenario results"><div id="result-content"></div><div class="result-actions"><button class="btn btn-primary" id="save-scenario" type="button">${icon('save')}Save scenario</button><div class="action-group"><button class="btn" id="download" type="button">${icon('download')}Export CSV</button><button class="btn" id="share" type="button">${icon('link')}Copy scenario link</button></div></div></section></div><section class="saved-panel" aria-labelledby="saved-title"><div class="section-heading"><div><h2 id="saved-title" tabindex="-1">Compare your scenarios</h2><p>Save up to three ${mode==='business'?'business':'policy'} scenarios in this browser.</p></div><span class="tag" id="save-count">0 / 3 saved</span></div><div id="saved-content"></div></section><div class="below-lab"><div class="context-note"><h3>${mode==='business'?'The economics behind the decision':'A price signal. A distributional choice.'}</h3><p>${mode==='business'?'Carbon pricing changes the cost of emissions. A reduction can lower that charge alongside operating costs. Compare annual benefits with upfront investment to explore the trade-off.':'The carbon price sets the charge. The rebate share determines how much revenue goes back to households. In this model, emissions respond to the price, independently of how revenue is returned.'}</p></div><div class="context-note"><h3>Keep the assumptions in view</h3><p>${mode==='business'?'Simple payback assumes constant annual benefits. It excludes financing, depreciation, income taxes, discounting, and asset life. Operating cash surplus is not accounting net income.':'Direct charges and rebates omit wider effects on prices, employment, abatement costs, and welfare. Retained public funds are not assigned an extra emissions benefit.'} <a href="${REPO}/blob/main/docs/METHODOLOGY.md" target="_blank" rel="noreferrer">See every formula.</a></p></div></div>`;
 $('#scenario-form').addEventListener('submit',e=>e.preventDefault());
 $('#scenario-form').addEventListener('input',onInput);
 $('#reset').addEventListener('click',()=>{state[mode]={...defaults[mode]};persist();renderLab();$('#reset').focus();toast('Default assumptions restored.');});
 document.querySelectorAll('[data-preset]').forEach(b=>b.addEventListener('click',()=>{state[mode]={...presets[mode].find(p=>p.id===b.dataset.preset).input};persist();renderLab();document.querySelector(`[data-preset="${b.dataset.preset}"]`).focus();}));
 $('#save-scenario').addEventListener('click',saveScenario);
 $('#download').addEventListener('click',download);
 $('#share').addEventListener('click',share);
 renderResults();renderSaved();
}
function onInput(event){
 if(event.target.type==='range'){
   const el=event.target;const step=Number(el.dataset.step);el.step=String(step);
   el.value=String(Number((Number(el.min)+Math.round((el.valueAsNumber-Number(el.min))/step)*step).toFixed(8)));
 }
 const data={};let invalid=null;
 for(const el of $('#scenario-form').elements){if(!el.name)continue;const valid=el.value.trim()!==''&&el.validity.valid;el.setAttribute('aria-invalid',String(!valid));if(!valid&&!invalid)invalid=el;data[el.name]=el.valueAsNumber===0?0:el.valueAsNumber;}
 if(invalid){$('#form-error').textContent=`Enter a valid ${invalid.labels[0].textContent.toLowerCase()} between ${num(Number(invalid.min))} and ${num(Number(invalid.max))}. Results still show your last valid scenario.`;setActionsDisabled(true);return;}
 try{(mode==='business'?calculateBusiness:calculateScenario)(data);}catch{$('#form-error').textContent='Check the input values. Results still show your last valid scenario.';setActionsDisabled(true);return;}
 $('#form-error').textContent='';setActionsDisabled(false);state[mode]=data;persist();
 const key=event.target.name;if(formats[key]&&$(`#${key}-value`)){$(`#${key}-value`).textContent=formats[key](data[key]);event.target.setAttribute('aria-valuetext',formats[key](data[key]));}
 document.querySelectorAll('[data-preset]').forEach(b=>{const p=presets[mode].find(p=>p.id===b.dataset.preset);b.setAttribute('aria-pressed',String(Object.keys(data).every(k=>p.input[k]===data[k])));});
 renderResults();
}
function setActionsDisabled(value){['save-scenario','download','share'].forEach(id=>{$(`#${id}`).disabled=value;});}
function metric(label,value,detail,kind,featured=false){return `<article class="metric ${featured?'featured':''}"><p class="metric-label">${icon(kind)}${label}</p><p class="metric-value">${value}</p><p class="metric-detail">${detail}</p></article>`;}
function renderResults(){current=mode==='business'?calculateBusiness(state.business):calculateScenario(state.policy);$('#result-content').innerHTML=mode==='business'?businessResults(current):policyResults(current);const announcement=mode==='business'?`Annual cash benefit ${money(current.annualBenefit)}. ${current.avoidedTonnes>0&&current.avoidedTonnes<.1?'less than 0.1':num(current.avoidedTonnes,1)} tonnes avoided. Simple payback ${current.paybackYears===null?'not defined':years(current.paybackYears)+' years'}.`:`Annual dividend ${money(current.dividend)}. ${num(current.reductionRate*100,1)} percent modeled reduction.`;clearTimeout(announcementTimer);const region=$('#result-announcement');announcementTimer=setTimeout(()=>{region.textContent=announcement;},300);}
function cashflowChart(s){
 const points=Array.from({length:6},(_,year)=>({year,value:year*s.annualBenefit-s.input.investment}));
 const low=Math.min(0,...points.map(p=>p.value));const high=Math.max(0,...points.map(p=>p.value));const span=high-low||1;const min=low-span*.1;const max=high+span*.12;const x=year=>65+year*104;const y=value=>190-(value-min)/(max-min)*165;
 const d=points.map((p,i)=>`${i?'L':'M'} ${x(p.year)} ${y(p.value)}`).join(' ');const z=y(0);
 return `<svg class="cashflow" viewBox="0 0 620 230" role="img" aria-labelledby="cashflow-title cashflow-desc"><title id="cashflow-title">Five-year cumulative incremental cash flow</title><desc id="cashflow-desc">Starts at ${money(points[0].value===0?0:points[0].value)} in year zero and reaches ${money(points[5].value)} in year five. Assumes constant annual benefits of ${money(s.annualBenefit)} and no discounting.</desc><defs><linearGradient id="chart-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#cee68f" stop-opacity=".5"/><stop offset="1" stop-color="#cee68f" stop-opacity=".03"/></linearGradient></defs>${[low,(low+high)/2,high].filter((n,i,a)=>a.indexOf(n)===i).map(v=>`<line class="chart-grid" x1="65" x2="585" y1="${y(v)}" y2="${y(v)}"/><text class="chart-axis" x="55" y="${y(v)+4}" text-anchor="end">${cash(v)}</text>`).join('')}<line x1="65" x2="585" y1="${z}" y2="${z}" stroke="#a2b297" stroke-dasharray="4 4"/><path d="${d} L 585 190 L 65 190 Z" fill="url(#chart-fill)"/><path d="${d}" fill="none" stroke="#2b6147" stroke-width="2.5" stroke-linejoin="round"/>${points.map(p=>`<circle cx="${x(p.year)}" cy="${y(p.value)}" r="4" fill="#2b6147" stroke="white" stroke-width="2"/><text class="chart-axis" x="${x(p.year)}" y="216" text-anchor="middle">${p.year===0?'Today':'Year '+p.year}</text>`).join('')}</svg>`;
}
function businessResults(s){
 const payback=s.paybackYears===null?'—':s.paybackYears>0&&s.paybackYears<.1?'&lt;0.1':years(s.paybackYears);const tag=s.paybackYears===null?(s.annualBenefit===0?'No annual benefit':'Outside numeric range'):s.paybackYears===0?'No upfront cost':s.paybackYears<=5?'Break-even within 5 years':'Beyond 5 years';
 return `<div class="metrics">${metric('Annual cash benefit',cash(s.annualBenefit),'Savings + avoided carbon charge','wallet',true)}${metric('Emissions avoided',`${tonnes(s.avoidedTonnes)}<span class="metric-unit">t</span>`,`${formats.reductionPercent(s.input.reductionPercent)} of baseline CO₂e / year`,'leaf')}${metric('Simple payback',`${payback}${s.paybackYears!==null?'<span class="metric-unit">yrs</span>':''}`,s.paybackYears===null?'No finite payback at these inputs':'Upfront cost ÷ annual benefit','clock')}</div><section class="chart-panel"><div class="section-heading"><div><h2>When does the investment pay off?</h2><p>Cumulative incremental cash flow · illustrative USD</p></div><span class="tag ${s.paybackYears===null||s.paybackYears>5?'warn':''}">${tag}</span></div>${cashflowChart(s)}<p class="chart-note"><span class="legend-line"></span>Investment + recurring benefits · undiscounted</p><p class="chart-interpretation">${s.annualBenefit===0?'With no operating savings or avoided carbon charge, this scenario has no finite payback.':`By year five, modeled cumulative cash flow is <strong>${signed(s.annualBenefit*5-s.input.investment)}</strong>. Cumulative figures include the ${money(s.input.investment)} investment made today.`}</p></section><section class="table-panel"><h2>The annual business picture</h2><div class="table-scroll"><table><thead><tr><th scope="col">Measure</th><th scope="col">Current operations</th><th scope="col">With investment</th></tr></thead><tbody><tr><td>Emissions · t CO₂e</td><td>${tonnes(s.input.annualTonnes)}</td><td>${tonnes(s.remainingTonnes)}</td></tr><tr><td>Carbon charge</td><td>${money(s.baselineCarbonCost)}</td><td>${money(s.futureCarbonCost)}</td></tr><tr><td>Operating cash surplus</td><td>${money(s.baselineProfit)}</td><td>${money(s.futureProfit)}</td></tr><tr><td>Operating cash margin</td><td>${pct(s.baselineMargin)}</td><td>${pct(s.futureMargin)}</td></tr><tr><td>Cumulative through year one</td><td>—</td><td class="${s.yearOneNetBenefit>=0?'positive':'negative'}">${signed(s.yearOneNetBenefit)}</td></tr></tbody></table></div></section>`;
}
function policyResults(s){const max=Math.max(1,...s.households.map(h=>Math.abs(h.net)));return `<div class="metrics">${metric('Annual household dividend',cash(s.dividend),'Equal payment to each household','wallet',true)}${metric('Modeled emissions cut',`${num(s.reductionRate*100,1)}<span class="metric-unit">%</span>`,`${num(s.avoidedTonnes,2)} t CO₂e / household / year`,'leaf')}${metric('Retained public funds',cash(s.publicFundsPerHousehold),'Per household / year','people')}</div><section class="chart-panel"><div class="section-heading"><div><h2>Who receives more than they pay?</h2><p>Annual dividend minus carbon charge · USD per household</p></div><span class="tag">${s.input.carbonPrice===0?'No carbon charge':s.winners+' of 5 groups ≥ $0'}</span></div><div class="policy-bars" role="img" aria-label="Net annual transfers by income group. Rounded values are in the table below; CSV preserves calculation precision.">${s.households.map(h=>`<div class="policy-bar-row"><span>${h.label}</span><div class="bar-track"><span class="bar ${h.net>=0?'positive':'negative'}" style="width:${Math.abs(h.net)/max*48}%"></span></div><output class="${h.net>=0?'positive':'negative'}">${signed(h.net)}</output></div>`).join('')}</div><div class="bar-labels"><span>Net charge</span><span>Net dividend</span></div><p class="chart-interpretation">Collected revenue is balanced (amounts rounded): <strong>${money(s.averageTax)}</strong> per household becomes <strong>${money(s.dividend)}</strong> in dividends and <strong>${money(s.publicFundsPerHousehold)}</strong> in retained funds.</p></section><section class="table-panel"><h2>Five illustrative household groups</h2><div class="table-scroll"><table class="policy-table"><thead><tr><th scope="col">Income group</th><th scope="col">Income / yr</th><th scope="col">Charge / yr</th><th scope="col">Net transfer / yr</th></tr></thead><tbody>${s.households.map(h=>`<tr><td>${h.label}</td><td>${money(h.income)}</td><td>${money(h.tax)}</td><td class="${h.net>=0?'positive':'negative'}">${signed(h.net)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function renderSaved(){
 const saved=state.saved.filter(s=>s.mode===mode);$('#save-count').textContent=`${saved.length} / 3 saved`;
 $('#saved-content').innerHTML=saved.length?`<div class="saved-grid">${saved.map(s=>{const r=mode==='business'?calculateBusiness(s.input):calculateScenario(s.input);return `<article class="saved-item"><h3>${esc(s.name)}</h3><p>${formats.carbonPrice(s.input.carbonPrice)}${mode==='business'?` · ${num(s.input.reductionPercent,2)}% lower emissions`:` · ${num(s.input.rebateShare,2)}% returned`}</p><div class="saved-number">${cash(mode==='business'?r.annualBenefit:r.dividend)}</div><p>${mode==='business'?'annual cash benefit':'annual household dividend'}<br>${mode==='business'?(r.paybackYears===null?'No finite payback':years(r.paybackYears)+' years simple payback'):num(r.reductionRate*100,1)+'% modeled emissions cut'}</p><div class="saved-actions"><button type="button" data-load="${esc(s.id)}" aria-label="Load ${esc(s.name)}">Load</button><button type="button" data-remove="${esc(s.id)}" aria-label="Remove ${esc(s.name)}">Remove</button></div></article>`;}).join('')}</div>`:'<p class="empty-saved">A useful comparison starts with one scenario. Adjust your assumptions, then select “Save scenario.”</p>';
 document.querySelectorAll('[data-load]').forEach(b=>b.addEventListener('click',()=>{const found=state.saved.find(s=>s.id===b.dataset.load);state[mode]={...found.input};persist();renderLab();$('#reset').focus();toast(`${found.name} loaded.`);}));
 document.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',()=>{state.saved=state.saved.filter(s=>s.id!==b.dataset.remove);persist();renderSaved();$('#saved-title').focus();toast('Saved scenario removed.');}));
}
function saveScenario(){
 const own=state.saved.filter(s=>s.mode===mode);if(own.length>=3){toast('Three scenarios saved. Remove one to save another.');return;}
 if(own.some(s=>JSON.stringify(s.input)===JSON.stringify(state[mode]))){toast('This scenario is already saved. Change an assumption to compare.');return;}
 const n=[1,2,3].find(i=>!own.some(s=>s.name===`Scenario ${i}`));state.saved.push({id:globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`,mode,input:{...state[mode]},name:`Scenario ${n}`});persist();renderSaved();toast(storageWarning?'Scenario kept for this session. Browser storage is unavailable.':'Scenario saved in this browser.');
}
function download(){const csv=mode==='business'?businessToCSV(current):scenarioToCSV(current);const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`carbon-commons-${mode}-scenario.csv`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Scenario CSV exported with inputs and units.');}
async function share(){
 const url=new URL(location.href);url.hash=buildHash(mode,state[mode]);url.search='';
 try{await navigator.clipboard.writeText(url.href);toast('Scenario link copied. It contains your current input values.');}
 catch{let area=document.createElement('textarea');area.value=url.href;area.setAttribute('aria-label','Scenario link');area.style.cssText='position:fixed;left:20px;right:20px;bottom:85px;width:calc(100% - 40px);z-index:60;padding:14px';document.body.append(area);area.focus();area.select();toast('Copy the selected scenario link, then press Escape.');area.addEventListener('keydown',e=>{if(e.key==='Escape'){area.remove();$('#share').focus();}});area.addEventListener('blur',()=>area.remove(),{once:true});}
}
function renderContribute(){
 $('#app').innerHTML=`<div class="contribute-intro"><section class="contribute-hero"><span class="tag">Open source · MIT licensed</span><h2>Small contributions.<br>Useful climate conversations.</h2><p>Help make the economics of a lower-carbon economy easier to explore. Bring your business knowledge, research skills, or code.</p><a class="btn btn-primary" href="${REPO}" target="_blank" rel="noreferrer">Explore the repository</a></section><section class="roadmap-card"><h2>Choose a useful starting point</h2><div class="roadmap-step"><span class="step-marker">1</span><div><h3>Reproduce a scenario</h3><p>Try a preset, change an assumption, and export the numbers. Every formula is documented and tested.</p></div></div><div class="roadmap-step"><span class="step-marker">2</span><div><h3>Improve one thing</h3><p>Validate a business case, improve accessibility, or propose a sourced extension to the model.</p></div></div><div class="roadmap-step"><span class="step-marker">3</span><div><h3>Share your evidence</h3><p>Open a focused pull request with a reproducible example, your assumptions, and relevant tests.</p></div></div></section></div><section class="achievement-section"><h2>Three ways to make this better</h2><p>The project grows through useful work at the intersection of business, economics, and the environment.</p><div class="achievement-list"><article class="achievement-card"><span class="tag">Business</span><h3>Build a sourced case study</h3><p>Document a small-business transition with transparent costs, savings, emissions boundaries, and uncertainty.</p></article><article class="achievement-card"><span class="tag">Economics</span><h3>Test what drives the result</h3><p>Explore discounting, asset life, household incidence, or sensitivity. Explain where the simple model stops.</p></article><article class="achievement-card"><span class="tag">Environment</span><h3>Make emissions inputs stronger</h3><p>Propose a versioned emissions-factor dataset with sources, geographic scope, units, and licensing.</p></article></div></section><div class="below-lab"><div class="context-note"><h3>Contribute with confidence</h3><p><a href="${REPO}/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">Read the contribution guide</a>, browse <a href="${REPO}/issues" target="_blank" rel="noreferrer">open issues</a>, or ask a substantive question in <a href="${REPO}/discussions" target="_blank" rel="noreferrer">Discussions</a>.</p></div><div class="context-note"><h3>A deliberately transparent model</h3><p>Presets use hypothetical data. You can inspect <a href="${REPO}/blob/main/docs/METHODOLOGY.md" target="_blank" rel="noreferrer">the formulas and sources</a> and run the same numerical checks locally.</p></div></div>`;
}
function route(){const parsed=parseHash(location.hash);mode=parsed.mode;if(parsed.input){state[mode]=parsed.input;persist();}if(location.hash.includes('?'))history.replaceState(null,'',`${location.pathname}${location.search}#${mode}`);document.querySelectorAll('[data-route]').forEach(a=>{const selected=a.dataset.route===mode;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#page-title').innerHTML=mode==='business'?'Make the <em>green</em> case.':mode==='policy'?'A fairer path to <em>less.</em>':'Build something that <em>matters.</em>';$('#hero-copy').innerHTML=mode==='business'?'See what lower emissions could mean for your business.<br class="desktop-break"> Explore the trade-offs. Make the assumptions your own.':mode==='policy'?'Explore how carbon pricing and household rebates work together.<br class="desktop-break"> One price signal. Different effects across the income distribution.':'A shared space for better questions about business and the planet.<br class="desktop-break"> Start with a model. Make it more useful together.';document.title=`Carbon Commons — ${mode==='business'?'Business lab':mode==='policy'?'Policy lab':'Build together'}`;if(mode==='contribute')renderContribute();else renderLab();if(parsed.error)toast(parsed.error);}
document.querySelector('.skip-link').addEventListener('click',event=>{event.preventDefault();$('#main').focus();$('#main').scrollIntoView();});
window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY||event.key===null){const latest=loadState(storage);if(!latest.warning){state.saved=latest.state.saved;if(mode!=='contribute')renderSaved();}}});
window.addEventListener('hashchange',route);route();
